with matched_keys as (select id, customer_id from orders intersect all select id, customer_id from orders where store_id in (3, 4, 11)), verified as (select s.* from orders s join matched_keys k on s.id = k.id and s.customer_id = k.customer_id) select s.customer_id, s.store_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.shipping_fee, (select max(o2.discount) from orders o2 where o2.store_id = s.store_id) as max_order_discount from verified s order by discount desc
